int copy_file(const char *src, const char *dst) {
    int rc = -1;
    FILE *in = NULL, *out = NULL;
    if (!(in = fopen(src, "rb"))) return -1;   /* nothing acquired */
    if (!(out = fopen(dst, "wb"))) goto done;  /* one shared exit */
    rc = pump(in, out);                         /* 0 on success */
done:
    if (out) fclose(out);                       /* reverse order, */
    if (in)  fclose(in);                        /* idempotent     */
    return rc;
}
